<?php
namespace Tests\Feature;
use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Models\{User,Project,ProjectAttachment};use Illuminate\Support\Facades\{Hash,DB,Storage,Mail,Password};use Illuminate\Http\UploadedFile;use Illuminate\Support\Str;
class AdminPanelTest extends TestCase {
 use RefreshDatabase;
 private function signedIn(User $user){$this->app['auth']->forgetGuards();$this->withSession(['password_hash_web'=>$user->password]);return $this->actingAs($user);}
 public function test_cms_publish_is_versioned_and_releases_only_published_content():void{$admin=$this->user();$temp=sys_get_temp_dir().'/northbyte-cms-'.Str::uuid();mkdir($temp);config(['northbyte.root'=>$temp]);try{$content=$this->signedIn($admin)->getJson('/api/admin/content')->assertOk();$copy=collect($content->json('items'))->firstWhere('key','copy');$draft=$copy['draft'];$draft['en']['heroText']='Published test content';$this->putJson('/api/admin/content/copy',['draft'=>$draft,'version'=>1])->assertOk();$this->postJson('/api/admin/content/copy/publish',['version'=>1])->assertConflict();$this->postJson('/api/admin/content/copy/publish',['version'=>2])->assertOk();$this->getJson('/api/public/content')->assertOk()->assertJsonPath('copy.en.heroText','Published test content');$this->assertFileExists($temp.'/published-content.json');}finally{if(file_exists($temp.'/published-content.json'))unlink($temp.'/published-content.json');rmdir($temp);}}
 private function user(string $role='admin'):User{return User::create(['name'=>'Test '.$role,'email'=>Str::uuid().'@example.test','password'=>Hash::make('TestPassword2026!'),'role'=>$role,'status'=>'active']);}
 private function project(User $owner,?User $assigned=null):Project{return Project::create(['owner_id'=>$owner->id,'title'=>'Actual project','description'=>'Project description','status'=>'New Request','assigned_to'=>$assigned?->id,'types'=>['Web Application'],'details'=>[]]);}
 public function test_client_project_submission_checks_csrf_and_preserves_client_isolation():void{Storage::fake('local');$client=$this->user('client');$other=$this->user('client');$token=bin2hex(random_bytes(32));$csrf=bin2hex(random_bytes(32));config(['northbyte.origin'=>'http://workspace.test']);DB::table('sessions')->insert(['token'=>hash('sha256',$token),'user_id'=>$client->id,'csrf'=>$csrf,'expires'=>(int)(microtime(true)*1000)+600000]);$this->withCredentials()->withUnencryptedCookie('nb_session',$token)->withHeader('Origin','http://workspace.test');$this->postJson('/api/client/projects',['title'=>'Client submission','description'=>'A private product'])->assertForbidden();$this->withHeader('X-CSRF-Token',$csrf);$response=$this->post('/api/client/projects',['project'=>json_encode(['title'=>'Client submission','description'=>'A private product','owner_id'=>$other->id,'status'=>'Completed'])],['Accept'=>'application/json'])->assertCreated()->assertJsonPath('owner_id',$client->id)->assertJsonPath('status','New Request');$id=$response->json('id');$file=UploadedFile::fake()->createWithContent('brief.pdf',"%PDF-1.7\nPrivate project brief");$upload=$this->post('/api/client/projects/'.$id.'/files',['file'=>$file,'client_visible'=>0],['Accept'=>'application/json'])->assertCreated()->assertJsonPath('client_visible',true);$fileId=$upload->json('id');$this->get('/api/client/files/'.$fileId)->assertOk();$otherToken=bin2hex(random_bytes(32));DB::table('sessions')->insert(['token'=>hash('sha256',$otherToken),'user_id'=>$other->id,'csrf'=>$csrf,'expires'=>(int)(microtime(true)*1000)+600000]);$this->app['auth']->forgetGuards();$this->withUnencryptedCookie('nb_session',$otherToken)->get('/api/client/files/'.$fileId)->assertForbidden();$this->getJson('/api/client/projects/'.$id)->assertForbidden();}
 public function test_legacy_scrypt_verification_uses_an_isolated_fixture():void{$code='import{ scryptSync }from"node:crypto";process.stdout.write("00000000000000000000000000000000:"+scryptSync("FixturePassword2026!","00000000000000000000000000000000",64).toString("hex"));';$process=new \Symfony\Component\Process\Process([config('northbyte.node_binary'),'--input-type=module','-e',$code]);$process->mustRun();$hash=trim($process->getOutput());$this->assertTrue(\App\Services\PasswordBridge::check('FixturePassword2026!',$hash));$this->assertFalse(\App\Services\PasswordBridge::check('WrongFixturePassword',$hash));}
 public function test_guests_and_clients_cannot_access_admin_resources():void{$this->get('/admin/dashboard')->assertRedirect('/admin/login');$this->getJson('/api/admin/overview')->assertUnauthorized();$client=$this->user('client');$this->signedIn($client)->getJson('/api/admin/clients')->assertForbidden();$this->signedIn($client)->get('/admin/projects')->assertForbidden();$this->postJson('/api/admin/login',['email'=>$client->email,'password'=>'TestPassword2026!'])->assertUnprocessable();}
 public function test_admin_login_session_and_logout_work():void{$admin=$this->user();$this->postJson('/api/admin/login',['email'=>$admin->email,'password'=>'wrong'])->assertUnprocessable();$this->postJson('/api/admin/login',['email'=>$admin->email,'password'=>'TestPassword2026!'])->assertOk()->assertCookie('nb_session')->assertJsonPath('user.role','admin');$this->getJson('/api/admin/session')->assertOk()->assertJsonPath('user.id',$admin->id);$this->postJson('/api/admin/logout')->assertOk();$this->assertDatabaseHas('activity_logs',['action'=>'admin.login','actor_id'=>$admin->id]);$this->assertDatabaseMissing('sessions',['user_id'=>$admin->id]);}
 public function test_project_creation_status_versioning_and_audit():void{$admin=$this->user();$client=$this->user('client');$response=$this->signedIn($admin)->postJson('/api/admin/projects',['owner_id'=>$client->id,'title'=>'Client product','description'=>'Build a client product','types'=>['Web Application']])->assertCreated();$id=$response->json('id');$this->patchJson('/api/admin/projects/'.$id,['status'=>'Under Review','version'=>1])->assertOk()->assertJsonPath('status','Under Review')->assertJsonPath('version',2);$this->patchJson('/api/admin/projects/'.$id,['status'=>'Completed','version'=>1])->assertConflict();$this->patchJson('/api/admin/projects/'.$id,['status'=>'Not a status','version'=>2])->assertUnprocessable();$this->assertDatabaseHas('activity_logs',['action'=>'project.updated','target_id'=>$id]);}
 public function test_team_members_only_see_assigned_projects_and_cannot_manage_roles():void{$member=$this->user('team_member');$other=$this->user('team_member');$client=$this->user('client');$mine=$this->project($client,$member);$theirs=$this->project($client,$other);$this->signedIn($member)->getJson('/api/admin/projects')->assertOk()->assertJsonCount(1,'data');$this->getJson('/api/admin/projects/'.$theirs->id)->assertForbidden();$this->patchJson('/api/admin/projects/'.$mine->id,['status'=>'In Development','version'=>1,'assigned_to'=>$other->id])->assertOk()->assertJsonPath('assigned_to',$member->id);$this->getJson('/api/admin/team')->assertForbidden();$this->postJson('/api/admin/team',['role'=>'super_admin'])->assertForbidden();}
 public function test_internal_notes_do_not_appear_in_client_project_responses():void{$admin=$this->user();$client=$this->user('client');$other=$this->user('client');$project=$this->project($client);$this->signedIn($admin)->postJson('/api/admin/projects/'.$project->id.'/notes',['body'=>'CONFIDENTIAL ADMIN NOTE'])->assertOk();$token=bin2hex(random_bytes(32));DB::table('sessions')->insert(['token'=>hash('sha256',$token),'user_id'=>$client->id,'csrf'=>str_repeat('a',64),'expires'=>(int)(microtime(true)*1000)+600000]);$this->app['auth']->forgetGuards();$this->withCredentials()->withUnencryptedCookie('nb_session',$token)->getJson('/api/client/projects/'.$project->id)->assertOk()->assertDontSee('CONFIDENTIAL ADMIN NOTE')->assertJsonMissingPath('internal_notes');$otherProject=$this->project($other);$this->withCredentials()->withUnencryptedCookie('nb_session',$token)->getJson('/api/client/projects/'.$otherProject->id)->assertForbidden();}
 public function test_private_upload_download_and_file_authorization():void{Storage::fake('local');$admin=$this->user();$client=$this->user('client');$member=$this->user('team_member');$project=$this->project($client);$file=UploadedFile::fake()->createWithContent('brief.pdf',"%PDF-1.7\nA brief");$response=$this->signedIn($admin)->post('/api/admin/projects/'.$project->id.'/files',['file'=>$file,'client_visible'=>1],['Accept'=>'application/json'])->assertCreated();$id=$response->json('id');$attachment=ProjectAttachment::findOrFail($id);Storage::disk('local')->assertExists($attachment->path);$this->get('/api/admin/files/'.$id)->assertOk()->assertHeader('X-Content-Type-Options','nosniff');$this->signedIn($member)->get('/api/admin/files/'.$id)->assertForbidden();$this->signedIn($admin)->post('/api/admin/projects/'.$project->id.'/files',['file'=>UploadedFile::fake()->createWithContent('fake.png','<script>bad</script>')],['Accept'=>'application/json'])->assertUnprocessable();$this->deleteJson('/api/admin/files/'.$id)->assertOk();$this->get('/api/admin/files/'.$id)->assertNotFound();$this->assertDatabaseHas('activity_logs',['action'=>'file.deleted','target_id'=>$project->id]);}
 public function test_super_admin_role_management_and_last_admin_protection():void{$super=$this->user('super_admin');$admin=$this->user();$this->signedIn($admin)->getJson('/api/admin/settings')->assertForbidden();$this->signedIn($super)->postJson('/api/admin/team',['name'=>'New member','email'=>'new-member@example.test','role'=>'team_member','status'=>'active','password'=>'SafePassword2026!'])->assertOk();$member=User::where('email','new-member@example.test')->firstOrFail();$this->assertTrue(Hash::check('SafePassword2026!',$member->password));$this->signedIn($super)->patchJson('/api/admin/team/'.$super->id,['name'=>$super->name,'email'=>$super->email,'role'=>'admin','status'=>'active'])->assertUnprocessable();$this->assertDatabaseHas('activity_logs',['action'=>'team.created','target_id'=>$member->id]);}
 public function test_suspension_revokes_sessions_and_blocks_access():void{$admin=$this->user();$client=$this->user('client');DB::table('sessions')->insert(['token'=>str_repeat('a',64),'user_id'=>$client->id,'csrf'=>str_repeat('b',64),'expires'=>9999999999999]);$this->signedIn($admin)->patchJson('/api/admin/clients/'.$client->id,['status'=>'suspended'])->assertOk();$this->assertDatabaseMissing('sessions',['user_id'=>$client->id]);$admin->status='suspended';$admin->save();$this->signedIn($admin)->getJson('/api/admin/overview')->assertForbidden();}
 public function test_notifications_are_owner_scoped_and_readable():void{$admin=$this->user();$other=$this->user();$client=$this->user('client');$project=$this->project($client);$this->signedIn($admin)->patchJson('/api/admin/projects/'.$project->id,['status'=>'Under Review','version'=>1])->assertOk();$response=$this->getJson('/api/admin/notifications')->assertOk();$this->assertGreaterThan(0,$response->json('unread'));$this->postJson('/api/admin/notifications/read',[])->assertOk();$this->assertDatabaseMissing('admin_notifications',['user_id'=>$admin->id,'read_at'=>null]);$this->assertDatabaseHas('admin_notifications',['user_id'=>$other->id,'read_at'=>null]);}
 public function test_overview_and_content_use_real_data_and_drafts_stay_private():void{$admin=$this->user();$client=$this->user('client');$this->project($client);$this->signedIn($admin)->getJson('/api/admin/overview?days=7')->assertOk()->assertJsonPath('stats.clients',1)->assertJsonPath('stats.pending',1)->assertJsonCount(7,'series');$content=$this->getJson('/api/admin/content')->assertOk();$copy=collect($content->json('items'))->firstWhere('key','copy');$draft=$copy['draft'];$draft['en']['heroText']='A draft only';$this->putJson('/api/admin/content/copy',['draft'=>$draft,'version'=>$copy['version']])->assertOk();$this->getJson('/api/public/content')->assertOk()->assertDontSee('A draft only');$this->putJson('/api/admin/content/copy',['draft'=>['bad'=>'shape'],'version'=>2])->assertUnprocessable();}
 public function test_password_changes_and_profile_preferences_are_validated():void{$admin=$this->user();$this->signedIn($admin)->patchJson('/api/admin/profile',['current_password'=>'wrong','password'=>'ChangedPassword2026!','password_confirmation'=>'ChangedPassword2026!'])->assertUnprocessable();$this->patchJson('/api/admin/profile',['locale'=>'fa','notification_preferences'=>['in_app'=>true,'email'=>false]])->assertOk()->assertJsonPath('user.locale','fa');$this->patchJson('/api/admin/profile',['current_password'=>'TestPassword2026!','password'=>'ChangedPassword2026!','password_confirmation'=>'ChangedPassword2026!'])->assertOk();$this->assertTrue(Hash::check('ChangedPassword2026!',$admin->fresh()->password));}
}
